const { syncPages } = require('./objects/pages');
const { syncBlogs } = require('./objects/blogs');
const { syncArticles } = require('./objects/articles');
const { syncCollections } = require('./objects/collections');
const { syncProducts } = require('./objects/products');
const { syncMedia } = require('./objects/media');
const { syncMenus } = require('./objects/menus');
const { syncThemes } = require('./objects/themes');

const OBJECT_EXECUTORS = Object.freeze({
  pages: syncPages,
  blogs: syncBlogs,
  articles: syncArticles,
  collections: syncCollections,
  products: syncProducts,
  media: syncMedia,
  menus: syncMenus,
  themes: syncThemes
});

const UNSUPPORTED_SYNC_OBJECT_TYPES = Object.freeze([
  'metafields',
  'metaobjects',
  'selling plans'
]);

function isUnsupportedObjectType(objectType) {
  return UNSUPPORTED_SYNC_OBJECT_TYPES.includes(objectType);
}

function createUnsupportedObjectResult(objectType) {
  return {
    status: 'skipped',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [`${objectType} sync is unsupported.`],
    errors: [],
    summary: {
      unsupported: true,
      placeholder: true
    }
  };
}

function getObjectExecutor(objectType) {
  return OBJECT_EXECUTORS[objectType] || null;
}

module.exports = {
  OBJECT_EXECUTORS,
  UNSUPPORTED_SYNC_OBJECT_TYPES,
  isUnsupportedObjectType,
  createUnsupportedObjectResult,
  getObjectExecutor
};
